import {S,term as T,step as P,check as Q,task as A,lesson as L} from './shared.js';
export default [
L(12,1,{
 title:'复现实验：让另一个人从配置得到你的结论',summary:'从一个干净的运行目录重新执行，验证报告依赖的代码、数据和恢复过程是否齐全。',prerequisites:['w11-l3','w3-l3'],
 terms:[T('可复现性 reproducibility','别人或未来的自己能依据记录重做实验，并在声明的精度范围内检查结论。','相同配置不一定保证跨硬件逐位相同，需要说明预期一致性。'),T('最小复现','保留问题关键条件、去掉无关复杂性的可运行案例。','先在小环境重现某种 mask 或更新错误。'),T('环境清单','依赖、硬件、精度和运行方式的记录。','Python、PyTorch 版本、设备和实际命令。'),T('恢复审计','对保存和加载训练状态的正确性做对照验证。','比较连续运行与中断后恢复，而不是只看加载函数没报错。')],
 sections:[P('第 1 步：用陌生读者视角重跑','新建一个独立输出目录，按 README 从环境准备、数据准备到训练和评测完整执行。不要依赖当前 shell 隐藏的变量、临时文件或未提交代码。','记录每个必须手动补的步骤，把它补进说明或脚本。项目能在自己旧目录运行，不代表别人拿到仓库就能复现。'),P('第 2 步：判断何种一致性是合理目标','同一简单 CPU 流程可以尝试严格比较数值；跨硬件、不同并行算子或精度时，应说明容差与统计范围。相同 seed 是必要记录之一，不是全部保证。','如果核心结论只在一个极小的数值差异上成立，硬件和随机性波动就很重要。优先报告结论对这些变化是否稳健。'),P('第 3 步：单独验证恢复','在支持完整续训的实现里，比较训练 N 步与训练 K 步保存恢复后到 N 步。对齐配置、数据顺序和随机条件，检查恢复时学习率、优化器统计、步数和下一个样本。','课程提供的 tiny_lm 和 tiny_world_model 脚本只保存若干状态，未提供完整 --resume 流程。因此可先审查它们的保存字段，再在已实现恢复的项目上做实验，不能运行不存在的参数。'),P('第 4 步：交付可复查而非不可搬动的大目录','公开作品可以包括小数据生成器、配置、核心代码、结果摘要与失败分析；大型权重或内部数据按允许的方式另行管理。别人应先能在小规模配置上验证关键机制。','保留“已实测”和“仅支持但未测试”的边界。CPU 跑通不能冒充 H20 多卡已验证；静态看源码不能冒充真实运行已验证。')],
 worked:{title:'复现检查应找出隐藏依赖',steps:['在新输出目录使用 README 命令运行。','若失败于某个本地绝对路径，说明数据或配置定位没有写完整。','改成明确的参数或相对路径，再从头检查。','只有得到可追溯结果后，才把该运行标为已复现。'],takeaway:'复现是实际执行与比较，不是给报告加一个“可复现”标签。'},
 example:{code:'continuous = [0.10, 0.08, 0.06]\nresumed = [0.10, 0.080001, 0.06]\ntolerance = 1e-5\nmax_difference = max(abs(a-b) for a,b in zip(continuous,resumed))\nprint("within tolerance", max_difference <= tolerance)',output:'within tolerance True',explanation:'这里仅演示容差比较。真实恢复审计还要检查数据、优化器等状态，不能只对比三项损失。'},
 checks:[Q('相同 seed 能保证任何硬件都逐位相同吗？','除了随机数还有哪些计算差异？','不能。硬件、算子、并行顺序和精度都可能影响数值，需声明复现标准。',1),Q('加载权重没有报错，是否说明完整 resume 正确？','后续更新还依赖什么？','不能。还需验证优化器、调度、数据位置和随机状态等是否正确恢复。',2)],
 practice:{title:'做一次别人能照着执行的复现',steps:[A('按自己的 README 在新目录跑最小配置。','运行命令、依赖和输入都完整。','不要在失败后偷偷使用未写入文档的手工步骤。'),A('检查报告每个主张对应哪项运行证据。','未验证项被单独列出。','“理论上支持”不是“实测通过”。'),A('为恢复功能建立连续/中断对照计划，已有实现则执行。','不支持时明确说明限制并列出需补的状态。','不要把仅保存 checkpoint 写成已经完整续训。')]},sources:[S.repro,S.checkpoint]
}),
L(12,2,{
 title:'算法答辩：从解释概念，到用证据回答追问',summary:'围绕你的实际项目练习模型、训练和评测三类问答，形成有依据的工程判断。',prerequisites:['w11-l3','w9-l3','w10-l3'],
 terms:[T('建模选择','决定输入、输出、表示、结构和目标怎样匹配任务。','为何预测未来 latent，是否需要动作条件。'),T('训练选择','决定数据、更新范围、优化器和计算预算。','为何选 LoRA、某种学习率或梯度窗口。'),T('证据链','让结论可以沿配置、代码、实验与样本逐项核查的连接。','某项指标改进对应哪组运行，是否控制了其他条件。'),T('消融追问','要求解释某个组件是否有用、拿掉会怎样的检查。','动作输入、输入噪声或记忆的价值分别如何验证。')],
 sections:[P('第 1 步：用两分钟描述一个完整系统','从任务开始：输入是什么，输出是什么，如何构造目标，模型怎样计算，哪些参数更新，用什么评测。先形成一条完整路线，再补细节。','不要一上来堆“Transformer、KDA、JEPA、RLHF”作为能力证明。每个名称都必须对应一个具体职责和可检查实现。'),P('第 2 步：回答“为什么这样选”','选择一个方法，需要说明适用问题、可选替代、资源限制和已知代价。例如 LoRA 降低可训练参数开销，却限制更新空间；表征预测节约像素负担，却可能丢掉任务细节。','没有做过的对照不要编结论。可以说当前选择来自资源约束，尚未比较另一方案，并给出会怎样比较的协议。'),P('第 3 步：回答“出了问题怎么办”','从失败现象提出候选解释，再按检查成本和辨别力排序。比如长期预测漂移，先查评测是否自由运行、动作是否生效、状态边界是否正确，再尝试训练技巧。','区分知识陈述和实践证据：“我知道 detach 的含义”与“我在项目里通过梯度路径检查验证它的边界”是不同层级。两者都可以诚实陈述。'),P('第 4 步：做一次带追问的答辩','让同事或自己追问：指标是否匹配目标？为什么不是数据问题？如果预算翻倍结论会变吗？你最不确定的部分是什么？用实际记录回答，不依赖临场记忆。','合格的课程产出不是保证三个月直接完成岗位转换，而是形成足够具体的代码、实验和解释能力，让下一步岗位实践有依据。')],
 worked:{title:'“为什么用 KDA”怎样回答才具体',steps:['任务需求：我们需要处理较长的连续历史。','结构解释：递归状态提供另一种历史存储和读取方式。','代价：状态容量与精确检索可能受限制，效率也需实际测量。','证据：列本次配置、长历史实验、吞吐与质量对照；未做的对照明确标出。'],takeaway:'专业回答包含选择、代价、证据和未知，而不只是方法全称。'},
 example:{code:'answer_outline = ["task and interfaces", "training choices", "controlled evidence", "limitations", "next experiment"]\nfor number, item in enumerate(answer_outline, 1):\n    print(number, item)',output:'1 task and interfaces\n2 training choices\n3 controlled evidence\n4 limitations\n5 next experiment',explanation:'这个提纲用于组织自己的项目答辩，内容必须由实际实现与实验填充。'},
 checks:[Q('别人问你没做过的全量微调对照，应该怎么回答？','区分已知事实与计划。','明确尚未验证，说明当前选择依据、预期取舍和具体对照设计，不编造结果。',1),Q('方法训练更快但任务质量下降，怎样评价？','先明确最终目标与资源约束。','并列报告速度、预算和质量，在目标约束下判断是否值得；不能只凭一个数字定优劣。',1)],
 practice:{title:'录一份有证据的十分钟项目答辩',steps:[A('用两分钟讲任务、模型、训练和评测。','不看术语表也能解释主要数据流。','若只能报模型名，回到输入输出和目标。'),A('选择一项改动，用三分钟讲基线、对照、结果和限制。','每个数字都能回到实验记录。','没有改善的试验同样可以展示诊断能力。'),A('记录三个答不上来的追问，并补一项真实检查。','把知识缺口转成下一步任务。','不要把背答案当作已经会实现。')]},sources:[S.cs336,S.kda,S.repro]
}),
L(12,3,{
 title:'把知识整理成作品：概念地图、世界模型与古琴迁移',summary:'将十二周连接为一套可继续扩展的方法，并把古琴项目重新定义为可以诊断的任务。',prerequisites:['w12-l1','w12-l2','w5-l3'],
 terms:[T('知识蒸馏 distillation','让学生模型学习教师输出或表示的一类训练方式。','与 DINO 等特定自监督方法有联系，但蒸馏不只用于视觉或自监督。'),T('MoE 混合专家','用路由选择部分专家模块参与计算的结构设计。','总参数和每次激活参数需要分别报告。'),T('SSM 状态空间模型','用状态更新和读取关系建模序列的一类方法；现代神经实现有多种形式。','与 KDA 都可讨论递归状态，但不能因此视为同一公式。'),T('约束解码','在生成或搜索时限制候选满足任务规则。','古琴指法可以先排除物理上不合法的动作，再比较可演奏性。')],
 sections:[P('第 1 步：按问题重建概念地图','模态回答处理什么；架构回答怎样计算；学习目标回答预测什么；训练阶段回答在生命周期何处训练；适配方法回答更新哪些参数；评测回答什么证据支持能力。一个模型可以在多个维度同时有标签。','现在再看“Decoder-only、AR、LoRA、SFT”就有依据：结构、预测组织、参数更新方式、示范学习任务分别说明不同问题。PT、rewardx 或内部名字仍需全称和代码上下文，不因为课程结束就自动确定含义。'),P('第 2 步：给新的名词保留正确入口','MoE 与 SSM 等没有在主线中完整实现的方法，先识别它们解决的问题和所属维度。不要把看到一个新缩写当作整个知识体系被推翻，也不要误称自己已经掌握其训练细节。','针对新方法，依次找输入输出、训练目标、更新范围、推理方式和证据。用一个最小算例建立直觉，再读关键实现和设计对照；这就是本课程可以迁移的方法。'),P('第 3 步：把世界模型产出整理成作品','作品应包括小规模基线、动作对照、单步与长期评测、状态边界说明、一次受控改动和复现步骤。对 OmniFM 可以形成内部源码阅读与实验报告，公开作品使用允许公开的数据与实现。','把知识水平分成能解释、能实现、做过对照三个层级。网页读完和选择题通过只是其中一部分，实际训练与证据需要持续补充。'),P('第 4 步：重新拆解古琴任务','输入不只是音高，可能还有节奏、上下文和演奏约束；输出是一段指法序列。同一音有多种正确指法，逐音唯一标签可能把合理替代也判错。先定义目标：可演奏、音色偏好、切换代价或风格。','从规则/搜索基线开始，按曲目划分验证，分别评估合法率、序列连贯性和专家偏好。之后再决定是监督序列模型、偏好学习，还是模型与约束搜索结合。不要在任务定义不清时直接扩大网络。'),P('第 5 步：用证据决定下一阶段','如果概念能解释但训练不会排错，继续补训练实验；如果实现能跑但结论不稳，补对照与评测；如果小模型扎实但真实工程陌生，沿实际配置深入 OmniFM 并承担一个可控改动。','三个月结束的输出是一组可审查的能力证据和明确的下一步，不是“掌握整个领域”的无条件保证。遇到疑问时可以回到具体课文、代码、原始资料和自己的实验。')],
 worked:{title:'古琴任务如何从“模型失败”变成可研究问题',steps:['定义输入单位：整句旋律及节奏，而不只孤立音高。','定义输出与约束：一段合法指法，允许多个合理答案。','建立规则或搜索基线，按完整曲目切分。','统计非法指法、跳转代价、专家偏好等失败，再决定补数据或改目标。'],takeaway:'任务、监督和评测先对齐，模型选择才有明确依据。'},
 example:{code:'model_card = {"task": "melody to playable fingering",\n              "split_unit": "whole piece",\n              "baseline": "rules plus search",\n              "metrics": ["validity", "transition cost", "expert preference"]}\nprint(model_card["split_unit"])\nprint(", ".join(model_card["metrics"]))',output:'whole piece\nvalidity, transition cost, expert preference',explanation:'这是古琴项目重新启动时的任务卡，不是已完成的指法生成模型。'},
 checks:[Q('新看到一种方法，第一步应该背缩写还是查任务接口？','哪一种信息能让它落到可检查的过程？','先查输入输出、目标、更新方式与评测，再将名称放进相应维度。',1),Q('古琴一个音有多个好指法，只用唯一标签准确率有什么局限？','合理但不同于标注的答案会怎样计分？','可能把合理替代判错，也忽略整段可演奏性；需要任务约束和偏好等补充评价。',3)],
 practice:{title:'交付作品与下一阶段学习清单',steps:[A('整理模型身份卡、可运行基线、实验报告和复现说明。','别人能检查至少一个核心结论。','未验证的功能清楚列出。'),A('给原先不清楚的概念标记当前层级：能解释、能实现或做过对照。','每项掌握判断有例子或运行记录。','看过定义不能直接标为做过对照。'),A('写古琴项目的一页重启方案，或选一个 OmniFM 小改动。','先明确数据、基线、评测和预算，再开始新训练。','不以模型名字代替问题定义。')]},sources:[S.cs336,S.repro,S.lora]
})];
